use maho_ext_pi_goal::goal::turn_usage::*;
use serde_json::{json,Value};
#[test]fn overflowing_finite_usage_preserves_nan_remaining(){let message=json!({"role":"assistant","usage":{"input":f64::MAX}});let mut tracker=TurnUsageTracker::default();tracker.note_message_end(&message);tracker.note_message_end(&message);assert!(tracker.take_pending().input.is_infinite());let remaining=tracker.take_remaining(&[message.clone(),message]);assert!(remaining.input.is_nan());}
fn assistant(input:u64,output:u64)->Value{json!({"role":"assistant","usage":{"input":input,"output":output,"cacheRead":0,"cacheWrite":0,"totalTokens":input+output}})}
#[test]fn flushed_usage_counted_once(){let mut tracker=TurnUsageTracker::default();let first=assistant(100,50);let second=assistant(10,5);tracker.note_message_end(&first);let pending=tracker.take_pending();tracker.note_message_end(&second);let remaining=tracker.take_remaining(&[first,second]);assert!((pending.input-100.0).abs()<f64::EPSILON);assert!((pending.output-50.0).abs()<f64::EPSILON);assert!((remaining.input-10.0).abs()<f64::EPSILON);assert!((remaining.output-5.0).abs()<f64::EPSILON);assert!((remaining.total_tokens-15.0).abs()<f64::EPSILON);}
#[test]fn accounting_window_discards_prior_usage(){let mut tracker=TurnUsageTracker::default();let before=assistant(1000,500);let after=assistant(10,5);tracker.note_message_end(&before);tracker.discard_pending();tracker.note_message_end(&after);let remaining=tracker.take_remaining(&[before,after]);assert!((remaining.input-10.0).abs()<f64::EPSILON);assert!((remaining.output-5.0).abs()<f64::EPSILON);assert!((remaining.total_tokens-15.0).abs()<f64::EPSILON);}
